PRAGMA foreign_keys = ON;
CREATE TABLE article_categories (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE articles (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, excerpt TEXT, content TEXT NOT NULL, content_format TEXT NOT NULL DEFAULT 'markdown', status TEXT NOT NULL DEFAULT 'draft', featured INTEGER NOT NULL DEFAULT 0, category_id TEXT, seo_title TEXT, seo_description TEXT, canonical_url TEXT, featured_image_url TEXT, og_image_url TEXT, author_name TEXT, published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY (category_id) REFERENCES article_categories(id) ON DELETE SET NULL);
CREATE TABLE tags (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE article_tags (article_id TEXT NOT NULL, tag_id TEXT NOT NULL, PRIMARY KEY(article_id, tag_id), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE);
CREATE TABLE tool_content (id TEXT PRIMARY KEY, tool_slug TEXT NOT NULL UNIQUE, custom_title TEXT, description TEXT, long_description TEXT, instructions TEXT, faq_json TEXT, seo_title TEXT, seo_description TEXT, featured INTEGER NOT NULL DEFAULT 0, popular INTEGER NOT NULL DEFAULT 0, new_badge INTEGER NOT NULL DEFAULT 0, is_visible INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE tool_relations (source_tool_slug TEXT NOT NULL, related_tool_slug TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(source_tool_slug, related_tool_slug));
CREATE TABLE article_tools (article_id TEXT NOT NULL, tool_slug TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(article_id, tool_slug), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE);
CREATE TABLE site_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE media (id TEXT PRIMARY KEY, r2_key TEXT NOT NULL UNIQUE, url TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, width INTEGER, height INTEGER, alt_text TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
